31	    /// Run a workflow with full interactive UI support.
32	    ///
33	    /// This is the primary execution entry point for interactive use. It manages
34	    /// the workflow lifecycle: building the execution plan, iterating over steps,
35	    /// updating the progress bar, tracking workflow state, and recording results.
36	    ///
37	    /// Step-level concerns (check evaluation, prompts, execution, recovery) are
38	    /// delegated to [`StepManager`].
39	    #[allow(clippy::too_many_arguments)]
40	    pub fn run_with_ui(
