1	//! Template resolution from multiple sources.
2	//!
3	//! Resolution order (first match wins):
4	//! 1. Project-local (.bivvy/templates/)
5	//! 2. User-local (~/.bivvy/templates/)
6	//! 3. Remote (by priority) - TODO in M11
7	//! 4. Built-in
8	
9	use crate::config::schema::TemplateSource as TemplateSourceConfig;
10	use crate::error::{BivvyError, Result};
11	use crate::registry::builtin::BuiltinLoader;
12	use crate::registry::local::LocalLoader;
13	use crate::registry::remote::RemoteLoader;
14	use crate::registry::template::{Template, TemplateSource};
15	use std::collections::HashMap;
16	use std::path::Path;
17	
18	/// A parsed template reference, optionally qualified by category.
19	///
20	/// Template references in config can use `category/name` syntax
21	/// (e.g., `rust/version-bump`) to disambiguate templates that share
22	/// a name across categories.
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	struct TemplateRef<'a> {
25	    name: &'a str,
26	    category: Option<&'a str>,
27	}
28	
29	impl<'a> TemplateRef<'a> {
30	    /// Parse a template reference string.
31	    ///
32	    /// Supports two forms:
33	    /// - `"name"` — unqualified lookup (first match wins)
34	    /// - `"category/name"` — qualified lookup (must match both name and category)
35	    fn parse(input: &'a str) -> Self {
36	        match input.split_once('/') {
37	            Some((category, name)) if !category.is_empty() && !name.is_empty() => Self {
38	                name,
39	                category: Some(category),
40	            },
41	            _ => Self {
42	                name: input,
43	                category: None,
44	            },
45	        }
46	    }
47	}
48	
49	/// Template registry that resolves templates from multiple sources.
50	#[derive(Debug, Clone)]
51	pub struct Registry {
52	    builtin: BuiltinLoader,
53	    local: LocalLoader,
54	    remote: RemoteLoader,
55	}
56	
57	impl Registry {
58	    /// Create a new registry for a project (without remote sources).
59	    pub fn new(project_root: Option<&Path>) -> Result<Self> {
60	        Ok(Self {
61	            builtin: BuiltinLoader::new()?,
62	            local: LocalLoader::new(project_root)?,
63	            remote: RemoteLoader::empty(),
64	        })
65	    }
66	
67	    /// Create a registry with remote template sources.
68	    ///
69	    /// HTTP sources go through the shared template cache; Git sources are
70	    /// cloned (or updated) into a `git/` subdirectory of the cache root.
71	    /// Git source URLs are validated up front: only `https://`, `ssh://`,
72	    /// `git://`, and `git@` SCP-style URLs are accepted.
73	    pub fn with_remote_sources(
74	        project_root: Option<&Path>,
75	        sources: &[TemplateSourceConfig],
76	    ) -> Result<Self> {
77	        use crate::config::schema::TemplateSourceKind;
78	        use crate::registry::fetch::validate_git_url;
79	
80	        // Validate Git source URLs up front so the user gets a clear error
81	        // before we hit the network or filesystem.
82	        for source in sources {
83	            if source.effective_kind() == TemplateSourceKind::Git {
84	                validate_git_url(&source.url).map_err(|e| BivvyError::ConfigValidationError {
85	                    message: format!("Invalid git template source URL: {}", e),
86	                })?;
87	            }
88	        }
89	
90	        let http_fetcher = crate::registry::fetch::HttpFetcher::new();
91	        let cache_dir = crate::cache::default_cache_dir();
92	        let git_fetcher = crate::registry::fetch::GitFetcher::new(cache_dir.join("git"));
93	        let cache = crate::cache::CacheStore::new(cache_dir);
94	
95	        let remote =
96	            RemoteLoader::new(sources, &http_fetcher, &git_fetcher, &cache).map_err(|e| {
97	                BivvyError::ConfigValidationError {
98	                    message: format!("Failed to load remote templates: {}", e),
99	                }
100	            })?;
101	
102	        Ok(Self {
103	            builtin: BuiltinLoader::new()?,
104	            local: LocalLoader::new(project_root)?,
105	            remote,
106	        })
107	    }
