+    fn concurrent_writes_do_not_corrupt_cache() {
+        let temp = TempDir::new().unwrap();
+        let root = temp.path().to_path_buf();
+
+        let num_threads = 8;
+        let iterations = 20;
+        let barrier = Arc::new(Barrier::new(num_threads));
+
+        let handles: Vec<_> = (0..num_threads)
+            .map(|i| {
+                let root = root.clone();
+                let barrier = Arc::clone(&barrier);
+                std::thread::spawn(move || {
+                    let store = CacheStore::new(&root);
+                    barrier.wait();
+                    for iter in 0..iterations {
+                        let content = format!("content from thread {} iter {}", i, iter);
+                        store
+                            .store("http:shared", "shared-template", &content, 3600)
+                            .unwrap();
+                    }
+                })
+            })
+            .collect();
+
+        for h in handles {
+            h.join().unwrap();
+        }
+
+        // After all concurrent writes, the cache must be in a consistent state:
+        // metadata must be valid JSON and content must be a complete string from
+        // one of the writers (not a torn/partial write).
+        let store = CacheStore::new(temp.path());
+        let entry = store
+            .load("http:shared", "shared-template")
+            .unwrap()
+            .expect("entry should exist after concurrent writes");
+        let content = store.read_content(&entry).unwrap();
+        assert!(
+            content.starts_with("content from thread "),
+            "content should be a complete write, got: {:?}",
+            content
+        );
+    }
+
+    #[test]
+    fn load_returns_none_for_corrupted_metadata() {
+        let temp = TempDir::new().unwrap();
+        let store = CacheStore::new(temp.path());
+
+        // Write valid entry first
+        store
+            .store("http:test", "template1", "good content", 3600)
+            .unwrap();
+
+        // Corrupt the metadata file
+        let meta_path = store
+            .content_path("http:test", "template1")
+            .with_extension("meta.json");
+        fs::write(&meta_path, "not valid json {{{").unwrap();
+
+        // load() should return None, not an error
+        let result = store.load("http:test", "template1").unwrap();
+        assert!(result.is_none());
+    }
+
+    #[test]
+    fn no_temp_files_left_after_store() {
+        let temp = TempDir::new().unwrap();
+        let store = CacheStore::new(temp.path());
+
+        store
+            .store("http:test", "template1", "content", 3600)
+            .unwrap();
+
+        // Check that no .tmp files remain
+        let tmp_files: Vec<_> = fs::read_dir(temp.path())
+            .unwrap()
+            .filter_map(|e| e.ok())
+            .filter(|e| e.file_name().to_string_lossy().starts_with(".tmp."))
+            .collect();
+        assert!(tmp_files.is_empty(), "temp files should be cleaned up");
+    }
